    <?php else: ?>
        <form class="resource-search" method="get" action="<?= e(basePath()) ?>/index.php"><input type="hidden" name="page" value="resources"><label class="sr-only" for="resource-query">Search career resources</label><input id="resource-query" name="q" type="search" value="<?= e($query ?? '') ?>" placeholder="Search CVs, interviews, digital skills..."><button class="button button-primary">Search</button><?php if (!empty($query)): ?><a class="button button-outline" href="<?= e(pageUrl('resources')) ?>">Clear</a><?php endif; ?></form>
        <?php if ($currentUser !== null && $currentUser['role'] === 'admin'): ?><details class="panel admin-create"><summary><strong>Publish a career resource</strong></summary><form class="form-stack" method="post" action="<?= e(pageUrl('resources')) ?>"><?= formToken() ?><input type="hidden" name="action" value="create_resource"><label class="field"><span>Title</span><input name="title" maxlength="180" required></label><label class="field"><span>Category</span><input name="category" maxlength="100" required placeholder="CV writing, interview preparation..."></label><label class="field"><span>Summary</span><textarea name="summary" rows="2" maxlength="500" required></textarea></label><label class="field"><span>Guide content</span><textarea name="content" rows="10" maxlength="30000" required></textarea></label><label class="checkbox-field"><input type="checkbox" name="is_published" value="1"><span>Publish immediately</span></label><button class="button button-primary">Save resource</button></form></details><?php endif; ?>
        <?php if ($resources !== []): ?><div class="resource-grid"><?php foreach ($resources as $item): ?><article class="resource-card"><span class="resource-category"><?= e($item['category']) ?></span><h3><a href="<?= e(pageUrl('resource', ['id' => (int) $item['id']])) ?>"><?= e($item['title']) ?></a></h3><p><?= e($item['summary']) ?></p><div class="resource-card-footer"><a class="text-link" href="<?= e(pageUrl('resource', ['id' => (int) $item['id']])) ?>">Read guide <span aria-hidden="true">→</span></a><?php if ($currentUser !== null && $currentUser['role'] === 'admin'): ?><form method="post" action="<?= e(pageUrl('resources')) ?>"><?= formToken() ?><input type="hidden" name="action" value="toggle_resource"><input type="hidden" name="resource_id" value="<?= e($item['id']) ?>"><button class="button button-text" type="submit">Unpublish</button></form><?php endif; ?></div></article><?php endforeach; ?></div>
